const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const { chromium } = require('playwright');
const { captureProfile } = require('./campervanfinder-profile.cjs');
const { validateSnapshot } = require('./campervanfinder-schema.cjs');
const root = path.resolve(__dirname, '..');

async function main() {
  const installedPython = process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'Programs', 'Python', 'Python313', 'python.exe');
  const python = process.env.PYTHON || (installedPython && fs.existsSync(installedPython) ? installedPython : 'python');
  execFileSync(python, [path.join(__dirname, 'extract-campervanfinder-reference.py')], { stdio: 'inherit' });
  const folder = path.join(root, 'references', 'campervanfinder');
  const reference = JSON.parse(fs.readFileSync(path.join(folder, 'reference-capture.json'), 'utf8'));
  const browser = await chromium.launch({ channel: process.env.CAMPERVANFINDER_TEST_BROWSER || 'chrome', headless: true });
  try {
    const context = await browser.newContext({ javaScriptEnabled: false });
    await context.route('**/*', route => route.abort());
    const page = await context.newPage();
    await page.setContent(fs.readFileSync(path.join(folder, 'vehicle-editor.snapshot.html'), 'utf8'), { waitUntil: 'domcontentloaded' });
    const postId = Number(new URL(reference.editUrl).searchParams.get('post'));
    const snapshot = await captureProfile(page, postId, { offline: true, editUrl: reference.editUrl, capturedAt: new Date(reference.savedAt).toISOString(), sourceFile: reference.file });
    validateSnapshot(snapshot, { sample: true });
    snapshot.audit.tabTables = await page.evaluate(tabs => {
      const result = {};
      for (const [index, tab] of Object.entries(tabs)) {
        if (!tab.content) continue;
        const document = new DOMParser().parseFromString(tab.content, 'text/html');
        result[index] = [...document.querySelectorAll('table.shop_attributes tr')].map(row => ({ label: row.querySelector('th')?.textContent.trim(), valueHtml: row.querySelector('td')?.innerHTML }));
      }
      return result;
    }, snapshot.data.productTabs.tabs);
    const file = path.join(folder, 'vehicle-profile-editor.sample.json');
    fs.writeFileSync(file, JSON.stringify(snapshot, null, 2) + '\n');
    console.log(`Sample saved: ${file}`);
  } finally { await browser.close(); }
}

if (require.main === module) main().catch(error => { console.error(error.message); process.exitCode = 1; });
module.exports = { main };

const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const { chromium } = require('playwright');
const { captureProfile } = require('./campervanfinder-profile.cjs');
const { validateSnapshot } = require('./campervanfinder-schema.cjs');

async function main() {
  const installed = process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'Programs/Python/Python313/python.exe');
  const python = process.env.PYTHON || (installed && fs.existsSync(installed) ? installed : 'python');
  execFileSync(python, [path.join(__dirname, 'extract-campervanfinder-nz-reference.py')], { stdio: 'ignore' });
  const folder = path.resolve(__dirname, '../references/campervanfinder');
  const inventory = JSON.parse(fs.readFileSync(path.join(folder, 'nz-editable-fields.inventory.json'), 'utf8'));
  const browser = await chromium.launch({ channel: process.env.CAMPERVANFINDER_TEST_BROWSER || 'chrome', headless: true });
  try {
    const context = await browser.newContext({ javaScriptEnabled: false });
    await context.route('**/*', route => route.abort());
    const page = await context.newPage();
    for (const reference of inventory) {
      await page.setContent(fs.readFileSync(path.join(folder, reference.decodedFile), 'utf8'), { waitUntil: 'domcontentloaded' });
      const postId = Number(new URL(reference.editUrl).searchParams.get('post'));
      const snapshot = await captureProfile(page, postId, { country: 'nz', offline: true, editUrl: reference.editUrl,
        capturedAt: new Date(reference.savedAt).toISOString(), sourceFile: reference.file });
      validateSnapshot(snapshot, { country: 'nz', sample: true });
      const file = reference.decodedFile.replace('.snapshot.html', '.sample.json');
      fs.writeFileSync(path.join(folder, file), JSON.stringify(snapshot, null, 2) + '\n');
      console.log(`Reference sample: ${file}; product ${postId}; ${snapshot.data.vehicle.name}; ${Object.keys(snapshot.data.productTabs.tabs).length} tabs. sampleOnly=true`);
    }
  } finally { await browser.close(); }
}
if (require.main === module) main().catch(error => { console.error(error.message); process.exitCode = 1; });
module.exports = { main };

"""Inspect saved MHTML editor controls without loading or executing their scripts."""

import json
import re
from email import policy
from email.parser import BytesParser
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import parse_qs, urlparse

ROOT = Path(__file__).resolve().parents[1]
VOID = set('area base br col embed hr img input link meta param source track wbr'.split())


class Node:
    def __init__(self, tag='', attrs=(), parent=None):
        self.tag, self.attrs, self.parent = tag, dict(attrs), parent
        self.children = []

    def nodes(self):
        for child in self.children:
            if isinstance(child, Node):
                yield child
                yield from child.nodes()

    def text(self):
        return ''.join(child.text() if isinstance(child, Node) else child for child in self.children)

    def has_class(self, name):
        return name in (self.attrs.get('class') or '').split()


class Document(HTMLParser):
    def __init__(self, html):
        super().__init__(convert_charrefs=True)
        self.root = Node()
        self.stack = [self.root]
        self.feed(html)

    def handle_starttag(self, tag, attrs):
        node = Node(tag, attrs, self.stack[-1])
        self.stack[-1].children.append(node)
        if tag not in VOID:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag not in VOID:
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        for index in range(len(self.stack) - 1, 0, -1):
            if self.stack[index].tag == tag:
                del self.stack[index:]
                break

    def handle_data(self, text):
        self.stack[-1].children.append(text)


def text_label(node):
    return re.sub(r'\s+', ' ', node.text()).strip()


def nearest(node, predicate):
    while node:
        if predicate(node):
            return node
        node = node.parent


def read_snapshot(path):
    if path.suffix == '.mhtml':
        message = BytesParser(policy=policy.default).parsebytes(path.read_bytes())
        part = next(part for part in message.walk() if part.get_content_type() == 'text/html')
        html = part.get_payload(decode=True).decode(part.get_content_charset() or 'utf-8', errors='replace')
        url = part.get('Content-Location') or message.get('Snapshot-Content-Location')
        saved_at = message.get('Date')
    else:
        html, url, saved_at = path.read_text(encoding='utf-8-sig'), None, None
    html = re.sub(r'\r+\n', '\n', html)
    root = Document(html).root
    nodes = list(root.nodes())
    ids = {node.attrs['id']: node for node in nodes if node.attrs.get('id')}
    fields = []
    for field in nodes:
        if not field.has_class('acf-field') or not field.attrs.get('data-name'):
            continue
        label = next((node for node in field.nodes() if node.tag == 'label' and nearest(node, lambda n: n.has_class('acf-label'))), None)
        box = nearest(field, lambda n: n.has_class('postbox'))
        heading = next((node for node in box.nodes() if node.tag == 'h2'), None) if box else None
        controls = []
        for node in field.nodes():
            if node.tag not in ('input', 'select', 'textarea'):
                continue
            if nearest(node.parent, lambda n: n.has_class('acf-field')) is not field:
                continue
            control = {key: value for key, value in node.attrs.items() if key in ('id', 'name', 'type', 'value', 'disabled', 'readonly', 'min', 'max', 'step', 'placeholder', 'multiple')}
            control['tag'] = node.tag
            if node.tag == 'textarea':
                control['value'] = node.text()
            if node.attrs.get('type') in ('checkbox', 'radio'):
                control['checked'] = 'checked' in node.attrs
                choice_label = nearest(node, lambda n: n.tag == 'label')
                control['label'] = text_label(choice_label) if choice_label else None
            if node.tag == 'select':
                control['options'] = [dict(value=option.attrs.get('value', option.text()), label=text_label(option), selected='selected' in option.attrs) for option in node.nodes() if option.tag == 'option']
                selected = [option['value'] for option in control['options'] if option['selected']]
                control['value'] = selected if 'multiple' in node.attrs else (selected[0] if selected else (control['options'][0]['value'] if control['options'] else None))
            controls.append(control)
        attachments = [dict(attachmentId=int(node.attrs['data-id']), position=index + 1) for index, node in enumerate(node for node in field.nodes() if node.has_class('acf-gallery-attachment') and (node.attrs.get('data-id') or '').isdigit())]
        fields.append(dict(name=field.attrs['data-name'], key=field.attrs.get('data-key'), type=field.attrs.get('data-type'), label=text_label(label) if label else None, group=text_label(heading) if heading else None, required=field.attrs.get('data-required'), controls=controls, attachments=attachments))
    taxonomies = {}
    for node in nodes:
        match = re.fullmatch(r'tax_input\[([^]]+)\]\[\]', node.attrs.get('name') or '')
        if node.tag != 'input' or node.attrs.get('type') != 'checkbox' or not match:
            continue
        label = nearest(node, lambda n: n.tag == 'label')
        taxonomies.setdefault(match[1], []).append(dict(termId=int(node.attrs['value']), label=text_label(label) if label else None, checked='checked' in node.attrs))
    post_id = ids.get('post_ID', Node()).attrs.get('value') or parse_qs(urlparse(url or '').query).get('post', [None])[0]
    permalink = next((node.attrs.get('href') for node in ids.get('sample-permalink', Node()).nodes() if node.tag == 'a'), None)
    preview = next((node for node in ids.get('postimagediv', Node()).nodes() if node.tag == 'img'), None)
    status = ids.get('post-status-display')
    return dict(file=path.name, savedAt=saved_at, editUrl=url, postId=int(post_id) if post_id else None, title=ids.get('title', Node()).attrs.get('value'), slug=ids.get('post_name', Node()).attrs.get('value') or ids.get('editable-post-name-full', Node()).text(), publicUrl=permalink, locale=next((node.attrs.get('lang') for node in nodes if node.tag == 'html'), None), statusDisplay=text_label(status) if status else None, featuredImageId=ids.get('_thumbnail_id', Node()).attrs.get('value'), featuredImagePreview=preview.attrs if preview else None, fields=fields, taxonomies=taxonomies)


def main():
    folder = ROOT / 'references' / 'motorhomehire'
    snapshots = [read_snapshot(path) for path in sorted(folder.glob('*.mhtml'))]
    output = folder / 'vehicle-editor-fields-comparison.json'
    output.write_text(json.dumps(snapshots, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    for snapshot in snapshots:
        print(f"{snapshot['file']}: post {snapshot['postId']}, {len(snapshot['fields'])} ACF fields, taxonomies {list(snapshot['taxonomies'])}")
    print(f'Inventory saved: {output}')


if __name__ == '__main__':
    main()

const fs = require('node:fs');
const paths = require('./paths.cjs');
const raw = fs.readFileSync(paths.editorMhtml, 'utf8');
const boundary = raw.match(/boundary="([^"]+)"/)[1];
const part = raw.split('--' + boundary).find(p => /Content-Type: text\/html/.test(p));
const body = part.slice(part.search(/\r?\n\r?\n/) + (part.includes('\r\n') ? 4 : 2));
const decoded = body.replace(/=\r?\n/g, '').replace(/=([0-9A-F]{2})/gi, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
const html = Buffer.from(decoded, 'latin1').toString('utf8');
fs.writeFileSync(paths.editorHtml, html);
const tags = html.match(/<(?:input|textarea|select|button|div)\b[^>]*>/gi) || [];
const attrs = tag => Object.fromEntries([...tag.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m => [m[1], m[2]]));
const fields = tags.map(attrs).filter(a => (a.class || '').split(/\s+/).includes('acf-field') && a['data-name']).map(a => ({name:a['data-name'],key:a['data-key'],type:a['data-type']}));
const controls = tags.filter(t => /^<(input|textarea|select|button)\b/i.test(t)).map(attrs).map(a => ({id:a.id,name:a.name,type:a.type}));
const snapshot = JSON.parse(fs.readFileSync(paths.currentReference, 'utf8'));
const report = {targetPostId:9927, sourceJsonPostId:snapshot.capture.postId, sourceJsonName:snapshot.data.vehicle.name, groups:Object.fromEntries(Object.entries(snapshot.data).map(([k,v]) => [k,Object.keys(v)])), acfFields:fields,controls};
report.fieldMappings = [{jsonPath:'data.vehicle.name',selector:'#title',type:'text'}];
for (const [group, values] of Object.entries(snapshot.data)) {
  if (group === 'vehicle' || group === 'taxonomies') continue;
  for (const [name, value] of Object.entries(values)) {
    const htmlName = group === 'featuresIcons' && name === 'sleeps' ? 'sleepsfeature' : name;
    const field = fields.find(f => f.name === htmlName);
    if (field) report.fieldMappings.push({jsonPath:`data.${group}.${name}`,selector:`.acf-field[data-key="${field.key}"]`,htmlName,type:field.type,jsonValueType:value === null ? 'null' : typeof value});
    else report.fieldMappings.push({jsonPath:`data.${group}.${name}`,type:name === 'featured_image' ? 'wordpress-media' : 'unmapped'});
  }
}
report.taxonomyInputNames = [...new Set(controls.map(c=>c.name).filter(n=>n && n.startsWith('tax_input[')))];
report.notes = ['JSON capture.postId is 1149; the test target is explicitly 9927.', 'featuresIcons.sleeps maps to HTML sleepsfeature; vehicleSpecifications.sleeps maps to HTML sleeps.', 'Text fields containing false need a defined empty/N/A conversion before future bulk edits.', 'Image metadata is snapshot information; media edits use attachment IDs and the media UI.', 'Only data.vehicle.name is currently implemented for writing.'];
fs.writeFileSync(paths.analysisReport, JSON.stringify(report, null, 2));
console.log(JSON.stringify({sourceJsonPostId:report.sourceJsonPostId,groups:report.groups,acfFields:fields,mainControls:controls.filter(a=>['title','publish','post_ID','post_type','content'].includes(a.id)||['post_ID','post_type'].includes(a.name))},null,2));

const { countrySite } = require('./campervanfinder-schema.cjs');
const { loadCampervanfinderPage } = require('./campervanfinder-loading.cjs');

async function targetEditor(page, postId, editUrl, { country = 'au', load = loadCampervanfinderPage, ...loadOptions } = {}) {
  const siteUrl = countrySite(country).origin;
  if (new URL(editUrl).origin !== siteUrl) throw new Error('Campervan Finder editor URL does not match the selected country.');
  await load(page, editUrl, { ...loadOptions, country, kind: 'editor', postId });
  const url = new URL(page.url());
  if (url.origin !== siteUrl || url.pathname !== '/wp-admin/post.php' || url.searchParams.get('post') !== String(postId)) throw new Error('Campervan Finder editor did not open. Check the WordPress login.');
  await page.locator('#title').waitFor({ state: 'visible' });
  if (await page.locator('[name="post_ID"]').inputValue() !== String(postId) || await page.locator('[name="post_type"]').inputValue() !== 'product') throw new Error('Unexpected product identity.');
}

// Hidden custom-tab textareas are legitimate form controls. Native setters and
// change events preserve the form/plugin workflow without clicking its nested Save buttons.
function productOperation({ operation, write = false }) {
  const elements = document.querySelectorAll(operation.selector);
  if (elements.length !== 1) throw new Error(`Missing or duplicate control: ${operation.jsonPath}`);
  const el = elements[0];
  if (el.disabled || el.readOnly) throw new Error(`Control is not editable: ${operation.jsonPath}`);
  if (operation.tabIndex !== undefined) {
    const box = el.closest('.woocommerce_product_tab');
    const token = operation.kind === 'custom' ? `product_tab_${operation.tabId}` : `core_tab_${operation.tabId}`;
    if (!box?.classList.contains(token)) throw new Error(`Tab identity changed for ${operation.jsonPath}. Capture the product again.`);
  }
  const editor = window.tinymce?.get?.(el.id);
  if (write) {
    // WordPress Text mode keeps the requested HTML as the saved source.
    if (editor && !editor.isHidden()) {
      if (!window.switchEditors?.go) throw new Error('WordPress Text mode switch is unavailable.');
      window.switchEditors.go(el.id, 'html');
      if (!editor.isHidden()) throw new Error(`Could not switch ${el.id} to Text mode.`);
    }
    const property = operation.type === 'checkbox' ? 'checked' : 'value';
    const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    Object.getOwnPropertyDescriptor(proto, property).set.call(el, operation.type === 'checkbox' ? operation.value : operation.value ?? '');
    el.dispatchEvent(new Event('input', { bubbles: true }));
    if (window.jQuery) window.jQuery(el).trigger('change');
    else el.dispatchEvent(new Event('change', { bubbles: true }));
  }
  if (operation.type === 'checkbox') return el.checked;
  return String(el.value).replace(/\r\n?/g, '\n');
}


module.exports = { targetEditor, productOperation };

const fs = require('node:fs');
const store = require('./catalog-store.cjs');
const gallery = require('./catalog-gallery.cjs');

const BOX = '#woocommerce-product-images';
const LIST = `${BOX} ul.product_images`;

// Runs in the editor. Check the real WooCommerce field and sortable callback,
// including on NZ, before clicking any gallery removal control.
function inspectGallery({ postId }) {
  if (document.querySelector('[name="post_ID"]')?.value !== String(postId) || document.querySelector('[name="post_type"]')?.value !== 'product') throw new Error('Unexpected gallery product identity.');
  const lists = document.querySelectorAll('#woocommerce-product-images ul.product_images');
  const inputs = document.querySelectorAll('input#product_image_gallery[name="product_image_gallery"]');
  const add = document.querySelectorAll('#woocommerce-product-images .add_product_images a');
  if (lists.length !== 1 || inputs.length !== 1 || inputs[0].disabled || add.length !== 1) throw new Error('The WooCommerce gallery controls are missing or ambiguous.');
  const images = [...lists[0].querySelectorAll(':scope > li.image[data-attachment_id]')];
  const ids = images.map(image => Number(image.dataset.attachment_id));
  if (ids.some(id => !Number.isSafeInteger(id) || id < 1) || new Set(ids).size !== ids.length || images.some(image => image.querySelectorAll('a.delete').length !== 1)) throw new Error('Invalid gallery image or removal control.');
  const stored = inputs[0].value.split(',').filter(Boolean).map(Number);
  if (JSON.stringify(stored) !== JSON.stringify(ids)) throw new Error('Gallery images and their stored form field disagree.');
  const jq = window.jQuery;
  if (!jq?.fn?.sortable || typeof jq(lists[0]).sortable('option', 'update') !== 'function') throw new Error('The WooCommerce gallery sortable handler is unavailable.');
  if (typeof window.wp?.media?.ajax !== 'function' || typeof window.wp?.media?.attachment !== 'function') throw new Error('The WordPress media API is unavailable.');
  const settingsPost = window.wp?.media?.view?.settings?.post?.id;
  if (settingsPost != null && Number(settingsPost) !== Number(postId)) throw new Error('The media uploader belongs to another product.');
  const filters = window._wpPluploadSettings?.defaults?.filters;
  const entries = Array.isArray(filters) ? filters : filters?.mime_types || [];
  return { ids, allowedExtensions: entries.flatMap(entry => String(entry.extensions || '').toLowerCase().split(',')).filter(Boolean) };
}

function reorderGallery({ expected }) {
  const list = document.querySelector('#woocommerce-product-images ul.product_images');
  const nodes = [...list.querySelectorAll(':scope > li.image[data-attachment_id]')];
  const indexed = new Map(nodes.map(node => [Number(node.dataset.attachment_id), node]));
  if (indexed.size !== nodes.length || nodes.length !== expected.length || expected.some(id => !indexed.has(id))) throw new Error('Gallery membership changed before reordering.');
  if (JSON.stringify(nodes.map(node => Number(node.dataset.attachment_id))) === JSON.stringify(expected)) return false;
  const jq = window.jQuery, update = jq(list).sortable('option', 'update');
  if (typeof update !== 'function') throw new Error('The gallery sortable handler disappeared.');
  for (const id of expected) list.append(indexed.get(id));
  jq(list).sortable('refresh');
  update.call(list, jq.Event('sortupdate'), { item: jq(indexed.get(expected[0])) });
  jq(list).trigger('sortupdate');
  return true;
}

async function openMedia(page, timeout) {
  const add = page.locator(`${BOX} .add_product_images a`);
  if (!await add.isVisible()) await page.locator(`${BOX} .handlediv`).click({ timeout });
  await add.click({ timeout });
  const modal = page.locator('.media-modal:visible');
  await modal.waitFor({ state: 'visible', timeout });
  await modal.locator('.media-frame-router .media-menu-item').filter({ hasText: /^Upload Files$/i }).click({ timeout });
  const select = modal.locator('.browser').filter({ hasText: /^Select Files$/i });
  await select.waitFor({ state: 'visible', timeout });
  if (await modal.locator('.media-button-select').count() !== 1 || await modal.locator('.media-modal-close').count() !== 1) throw new Error('Unexpected WordPress gallery upload modal.');
  return { modal, select };
}

async function mediaList(page, postId, timeout = 300000) {
  const result = await page.evaluate(async ({ postId, timeout }) => {
    const deadline = Date.now() + timeout, result = [], seen = new Set();
    // Legacy wp.media.query returns a mirrored Attachments collection whose
    // inherited fetch() has no URL. Read the same authenticated query action
    // directly, with explicit pagination and no stale collection cache.
    for (let paged = 1; ; paged++) {
      const remaining = deadline - Date.now();
      if (remaining <= 0) throw new Error('Timed out reading product media.');
      let timer;
      const pending = window.wp.media.ajax({ data: { action: 'query-attachments', post_id: Number(postId), query: { post_parent: Number(postId), posts_per_page: 100, paged, orderby: 'ID', order: 'ASC' } } });
      let items;
      try { items = await Promise.race([Promise.resolve(pending), new Promise((_, reject) => { timer = setTimeout(() => { pending.abort?.(); reject(new Error('Timed out reading product media.')); }, remaining); })]); }
      catch { throw new Error('Could not read the product Media Library query.'); }
      finally { clearTimeout(timer); }
      if (!Array.isArray(items)) throw new Error('Invalid product media response.');
      for (const item of items) {
        const id = Number(item.id);
        if (seen.has(id)) throw new Error('Product media pagination repeated an attachment; retry the read.');
        seen.add(id);
        result.push({ id, url: item.url, type: item.type, uploadedTo: Number(item.uploadedTo) });
      }
      if (items.length < 100) return result;
    }
  }, { postId, timeout });
  if (result.some(item => !Number.isSafeInteger(item.id) || item.id < 1 || item.uploadedTo !== Number(postId))) throw new Error('Could not obtain a complete product media baseline for upload recovery.');
  return result;
}

async function attachment(page, id, timeout = 300000) {
  return page.evaluate(async ({ id, timeout }) => {
    const model = window.wp.media.attachment(id);
    let timer;
    const pending = model.fetch();
    try { await Promise.race([Promise.resolve(pending), new Promise((_, reject) => { timer = setTimeout(() => { pending.abort?.(); reject(new Error('Timed out reading uploaded image metadata.')); }, timeout); })]); }
    catch { throw new Error(`Could not read uploaded image metadata for ${id}.`); }
    finally { clearTimeout(timer); }
    const item = model.toJSON();
    return { id: Number(item.id), url: item.url, filename: item.filename, title: item.title, type: item.type, uploadedTo: Number(item.uploadedTo) };
  }, { id, timeout });
}

async function matchesAsset(page, media, asset, origin, timeout) {
  if (media.type !== 'image' || typeof media.url !== 'string') return false;
  const url = new URL(media.url);
  if (url.origin !== origin || !url.pathname.startsWith('/wp-content/uploads/')) throw new Error('Gallery attachment has an unexpected source URL.');
  const result = await page.evaluate(async ({ url, timeout }) => {
    const response = await fetch(url, { credentials: 'same-origin', cache: 'no-store', signal: AbortSignal.timeout(timeout) });
    if (!response.ok) throw new Error(`Uploaded image read returned HTTP ${response.status}.`);
    const bytes = await response.arrayBuffer();
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    return { size: bytes.byteLength, sha256: [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('') };
  }, { url: url.href, timeout });
  return result.size === asset.size && result.sha256 === asset.sha256;
}

async function reconcileUpload(page, target, asset, entry, persist, timeout) {
  const origin = target.mapping.siteOrigin;
  if (entry.status === 'uploaded') {
    const media = await attachment(page, entry.attachmentId, timeout);
    if (media.id !== entry.attachmentId || media.uploadedTo !== Number(target.externalId) || !await matchesAsset(page, media, asset, origin, timeout)) throw new Error(`Previously uploaded image ${entry.attachmentId} no longer matches ${asset.filename}.`);
    return media;
  }
  if (entry.status !== 'submitting') return null;
  const candidates = (await mediaList(page, target.externalId, timeout)).filter(item => !entry.existingIds.includes(item.id));
  const matches = [];
  for (const item of candidates) if (await matchesAsset(page, item, asset, origin, timeout)) matches.push(item);
  if (matches.length !== 1) throw new Error(`Upload outcome is uncertain for ${asset.filename}: ${matches.length} matching new attachments. Reconcile this run before retrying; the file will not be uploaded again automatically.`);
  entry.status = 'uploaded'; entry.attachmentId = matches[0].id; persist();
  return attachment(page, entry.attachmentId, timeout);
}

async function clearSelection(modal, timeout) {
  const selected = modal.locator('.attachments .attachment.selected .check');
  while (await selected.count()) await selected.first().click({ timeout });
}

async function addUploaded(page, modal, id, { media, timeout }) {
  await modal.locator('.media-frame-router .media-menu-item').filter({ hasText: /^Media Library$/i }).click({ timeout });
  const tile = modal.locator(`.attachments .attachment[data-id="${id}"]`);
  if (!await tile.count() && media) {
    const search = modal.locator('.media-toolbar-primary input[type="search"]');
    await search.fill(String(media.title || media.filename).replace(/\.[^.]+$/, ''), { timeout });
    await search.press('Enter', { timeout });
  }
  await tile.waitFor({ state: 'visible', timeout });
  // Only the attachment confirmed for this file may be selected.
  for (const other of await modal.locator(`.attachments .attachment.selected:not([data-id="${id}"]) .check`).all()) await other.click({ timeout });
  if (!/(?:^|\s)selected(?:\s|$)/.test(await tile.getAttribute('class'))) await tile.click({ timeout });
  const selected = await modal.locator('.attachments .attachment.selected').evaluateAll(nodes => nodes.map(node => Number(node.getAttribute('data-id'))));
  if (!store.equal(selected, [id])) throw new Error('Media selection contains an unreviewed attachment.');
  await modal.locator('.media-button-select:not([disabled])').click({ timeout });
  await modal.waitFor({ state: 'hidden', timeout });
  await page.locator(`${LIST} > li.image[data-attachment_id="${id}"]`).waitFor({ state: 'attached', timeout });
}

async function uploadOne(page, target, asset, buffer, journal, persist, { timeout, log }) {
  let entry = journal.uploads.find(item => item.key === gallery.uploadKey(asset));
  let media = entry ? await reconcileUpload(page, target, asset, entry, persist, timeout) : null;
  const { modal, select } = await openMedia(page, timeout);
  await clearSelection(modal, timeout);
  if (!media) {
    const existingIds = (await mediaList(page, target.externalId, timeout)).map(item => item.id);
    const chooserResult = page.waitForEvent('filechooser', { timeout }).then(value => ({ value }), error => ({ error }));
    await select.click({ timeout });
    const chooser = await chooserResult;
    if (chooser.error) throw chooser.error;
    if (!entry) { entry = { key: gallery.uploadKey(asset), status: 'submitting', existingIds, attachmentId: null }; journal.uploads.push(entry); }
    else Object.assign(entry, { status: 'submitting', existingIds, attachmentId: null });
    persist(); // Persist intent before the irreversible Media Library upload.
    const responseResult = page.waitForResponse(response => {
      const url = new URL(response.url());
      return url.origin === target.mapping.siteOrigin && url.pathname === '/wp-admin/async-upload.php' && response.request().method() === 'POST';
    }, { timeout }).then(value => ({ value }), error => ({ error }));
    log(`Uploading ${asset.filename}.`);
    await chooser.value.setFiles({ name: asset.filename, mimeType: asset.mimeType, buffer }, { timeout });
    const result = await responseResult;
    if (result.error) throw result.error;
    let payload;
    try { payload = await result.value.json(); }
    catch { throw new Error(`Upload response for ${asset.filename} was not confirmed JSON. Resume this run to reconcile the uncertain attachment.`); }
    if (payload?.success === false) { entry.status = 'failed'; persist(); throw new Error(`WordPress rejected ${asset.filename}: ${payload.data?.message || 'upload failed'}`); }
    const id = Number(payload?.data?.id);
    if (!result.value.ok() || payload?.success !== true || !Number.isSafeInteger(id) || id < 1 || entry.existingIds.includes(id) || payload.data.type !== 'image') throw new Error(`Unconfirmed upload result for ${asset.filename}; resume this run before retrying.`);
    entry.status = 'uploaded'; entry.attachmentId = id; persist();
    media = { id, title: payload.data.title, filename: payload.data.filename };
  } else log(`Reusing confirmed upload ${entry.attachmentId} for ${asset.filename}.`);
  await addUploaded(page, modal, entry.attachmentId, { media, timeout });
}

async function applyGallery(page, target, context, { timeout = 300000, log = console.log } = {}) {
  if (!target.gallery) return { changed: false };
  const { root, journal, persistJournal } = context || {};
  if (!root || typeof persistJournal !== 'function') throw new Error('Gallery execution requires persistent run recovery state.');
  gallery.validateJournal(target, journal);
  const persist = () => { gallery.validateJournal(target, journal); persistJournal(journal); };
  const buffers = new Map();
  for (const asset of target.gallery.uploads) {
    const bytes = fs.readFileSync(store.inside(root, asset.path));
    if (bytes.length !== asset.size || gallery.digest(bytes) !== asset.sha256) throw new Error(`Gallery image changed since review: ${asset.filename}`);
    await page.evaluate(async ({ base64, type }) => {
      const bytes = Uint8Array.from(atob(base64), character => character.charCodeAt(0));
      const image = await createImageBitmap(new Blob([bytes], { type }));
      const valid = image.width > 0 && image.height > 0; image.close();
      if (!valid) throw new Error('Image cannot be decoded.');
    }, { base64: bytes.toString('base64'), type: asset.mimeType });
    buffers.set(gallery.uploadKey(asset), bytes);
  }
  const state = await page.evaluate(inspectGallery, { postId: target.externalId });
  for (const asset of target.gallery.uploads) if (state.allowedExtensions.length && !state.allowedExtensions.includes('*') && !state.allowedExtensions.includes(asset.filename.split('.').at(-1).toLowerCase())) throw new Error(`The site's uploader does not accept ${asset.filename}.`);
  // Reconcile prior submissions even if the final gallery is already saved.
  for (const asset of target.gallery.uploads) {
    const entry = journal.uploads.find(item => item.key === gallery.uploadKey(asset));
    if (entry && entry.status !== 'failed') await reconcileUpload(page, target, asset, entry, persist, timeout);
  }
  let expected = gallery.desiredIds(target, journal);
  if (expected && store.equal(state.ids, expected)) return { changed: false, expected };
  if (!store.equal(state.ids, target.gallery.baselineIds)) throw new Error('Live gallery conflict: the reviewed attachment IDs/order changed.');
  if (target.gallery.uploads.length) {
    const { modal } = await openMedia(page, timeout);
    await modal.locator('.media-modal-close').click({ timeout });
    await modal.waitFor({ state: 'hidden', timeout });
    // Check the product-specific media contract before removing any images.
    await mediaList(page, target.externalId, timeout);
  }
  const checked = await page.evaluate(inspectGallery, { postId: target.externalId });
  if (!store.equal(checked.ids, target.gallery.baselineIds)) throw new Error('Gallery changed during upload preflight.');
  for (const image of target.gallery.remove) {
    log(`Removing gallery position ${image.position} (attachment ${image.attachmentId}).`);
    const tile = page.locator(`${LIST} > li.image[data-attachment_id="${image.attachmentId}"]`);
    // The X shows only while hovered. A tile still sliding into place after the
    // previous removal can lose the hover, so hover and click again briefly.
    for (let attempt = 1; ; attempt++) {
      try {
        await tile.hover({ timeout });
        await tile.locator('a.delete').click({ timeout: Math.min(timeout, 5000) });
        break;
      } catch (error) {
        if (!(await tile.count())) break;
        if (attempt >= 6) throw error;
        log(`Gallery position ${image.position}: delete control not ready, retrying (${attempt}).`);
        await page.waitForTimeout(400);
      }
    }
    await tile.waitFor({ state: 'detached', timeout });
  }
  let current = await page.evaluate(inspectGallery, { postId: target.externalId });
  if (!store.equal(current.ids, target.gallery.retainedIds)) throw new Error('Gallery removal did not produce the reviewed retained images.');
  for (const asset of target.gallery.uploads) await uploadOne(page, target, asset, buffers.get(gallery.uploadKey(asset)), journal, persist, { timeout, log });
  expected = gallery.desiredIds(target, journal);
  await page.evaluate(reorderGallery, { expected });
  current = await page.evaluate(inspectGallery, { postId: target.externalId });
  if (!store.equal(current.ids, expected)) throw new Error('Gallery form value/order did not match the reviewed result.');
  return { changed: !store.equal(state.ids, expected), expected };
}

module.exports = { inspectGallery, reorderGallery, openMedia, mediaList, attachment, matchesAsset, reconcileUpload, applyGallery };

const { countrySite } = require('./campervanfinder-schema.cjs');

const DEFAULT_PAGE_TIMEOUT_MS = 300_000;

// Thumbnail ID inputs are intentionally optional: the legacy featured-image
// box uses media-upload.php and may never render one, even on a fully loaded page.
function inspectPageReadiness({ kind }) {
  const selectors = kind === 'editor'
    ? ['#title', '[name="post_ID"]', '[name="post_type"]', '#content', '#excerpt', '#postimagediv', '#woocommerce-product-data', '#woocommerce-product-images', '#product_catchecklist', '#_override_tab_layout', '#tax-input-product_tag']
    : ['.wp-list-table #the-list', '.tablenav.top .displaying-num'];
  const missing = selectors.filter(selector => !document.querySelector(selector));
  if (kind === 'editor' && document.querySelector('#title') && !document.querySelector('#title').value.trim()) missing.push('populated vehicle title');
  const busy = [...document.querySelectorAll('.spinner.is-active, .spinner.active, .blockUI.blockOverlay, #post[aria-busy="true"], .wp-list-table[aria-busy="true"], #publish.disabled, #publish[disabled], #publish[aria-disabled="true"], #save-post.disabled, #save-post[disabled]')].filter(el => {
    const style = getComputedStyle(el);
    return style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0' && el.getClientRects().length;
  }).map(el => el.id || el.className);
  const controls = kind === 'editor'
    ? '#title, #content, #excerpt, .woocommerce_product_tab input, .woocommerce_product_tab textarea, #product_catchecklist input, #woocommerce-product-images li.image, #postimagediv img'
    : '.wp-list-table #the-list, .tablenav.top';
  const signature = JSON.stringify([...document.querySelectorAll(controls)].map(el => [el.id, el.name, el.value ?? el.getAttribute('data-attachment_id') ?? el.getAttribute('src') ?? el.textContent, el.checked]));
  return { readyState: document.readyState, missing, busy, signature, postId: document.querySelector('[name="post_ID"]')?.value, postType: document.querySelector('[name="post_type"]')?.value };
}

async function waitForPageControls(page, { kind, postId, timeout = DEFAULT_PAGE_TIMEOUT_MS, log = console.log, pollMs = 250, settleMs = 1_000, resourceGraceMs = 15_000, heartbeatMs = 15_000 } = {}) {
  const start = Date.now(), deadline = start + timeout;
  let stableSince = start, signature, lastLog = start, state;
  while (Date.now() < deadline) {
    if (page.isClosed()) throw new Error('Automation tab closed while waiting for the page to finish loading.');
    try {
      state = await page.evaluate(inspectPageReadiness, { kind });
    } catch (error) {
      if (!/Execution context was destroyed|Cannot find context|because of a navigation/i.test(error.message)) throw error;
      // A navigation can replace the document while the readiness check runs.
      state = { readyState: 'loading', missing: ['new document'], busy: [], signature: null };
    }
    if (kind === 'editor' && ((state.postId && state.postId !== String(postId)) || (state.postType && state.postType !== 'product'))) throw new Error('Unexpected product identity while waiting for the editor.');
    if (state.signature !== signature || state.missing.length || state.busy.length) {
      stableSince = Date.now();
      signature = state.signature;
    }
    const elapsed = Date.now() - start;
    const controlsReady = !state.missing.length && !state.busy.length && state.readyState !== 'loading' && Date.now() - stableSince >= settleMs;
    if (controlsReady && (state.readyState === 'complete' || elapsed >= resourceGraceMs)) {
      if (state.readyState !== 'complete') log('Background resources are still loading; required page controls are complete and stable. Continuing.');
      return state;
    }
    if (Date.now() - lastLog >= heartbeatMs) {
      const detail = state.missing.length ? `waiting for ${state.missing.join(', ')}` : state.busy.length ? `busy: ${state.busy.join(', ')}` : 'waiting for document resources/controls to settle';
      log(`Still loading ${kind} (${Math.round(elapsed / 1_000)}s): document=${state.readyState}; ${detail}.`);
      lastLog = Date.now();
    }
    await page.waitForTimeout(Math.min(pollMs, Math.max(1, deadline - Date.now())));
  }
  const detail = state?.missing.length ? `Missing: ${state.missing.join(', ')}.` : state?.busy.length ? `Busy: ${state.busy.join(', ')}.` : `Document state: ${state?.readyState || 'unknown'}.`;
  throw new Error(`Timed out waiting for ${kind} controls after ${Math.round(timeout / 1_000)}s. ${detail}`);
}

async function loadCampervanfinderPage(page, url, options = {}) {
  const { kind = 'editor', postId, timeout = DEFAULT_PAGE_TIMEOUT_MS, log = console.log, heartbeatMs = 15_000 } = options;
  const siteUrl = countrySite(options.country || 'au').origin;
  if (new URL(url).origin !== siteUrl) throw new Error('Campervan Finder URL does not match the selected country.');
  if (!Number.isSafeInteger(timeout) || timeout <= 0) throw new Error('pageTimeoutMs must be a positive integer.');
  const start = Date.now();
  const timer = setInterval(() => log(`Still loading ${kind}: waiting for the document response (${Math.round((Date.now() - start) / 1_000)}s, limit ${Math.round(timeout / 1_000)}s).`), heartbeatMs);
  let response;
  try {
    // External images, embeds, and tracking scripts can hold the load event open
    // indefinitely. Wait for the document, then inspect the actual editor/list.
    response = await page.goto(url, { waitUntil: 'domcontentloaded', timeout });
  } catch (error) {
    throw new Error(`Could not load ${kind} document within ${Math.round(timeout / 1_000)}s: ${error.message}`, { cause: error });
  } finally { clearInterval(timer); }
  if (response && response.status() >= 400) throw new Error(`The ${kind} page returned HTTP ${response.status()}.`);
  const actual = new URL(page.url()), expected = new URL(url);
  if (actual.origin !== siteUrl || actual.pathname !== expected.pathname || (kind === 'editor' && actual.searchParams.get('post') !== String(postId)) || (kind === 'list' && actual.searchParams.get('post_type') !== 'product')) throw new Error(`The expected ${kind} page did not open. Check the WordPress login and URL.`);
  const remaining = Math.max(1, timeout - (Date.now() - start));
  return waitForPageControls(page, { ...options, kind, postId, log, timeout: remaining });
}

module.exports = { DEFAULT_PAGE_TIMEOUT_MS, inspectPageReadiness, waitForPageControls, loadCampervanfinderPage };

const fs = require('node:fs');
const path = require('node:path');
const { randomUUID } = require('node:crypto');
const { countrySite, countryForSite, SCHEMA_VERSION } = require('./campervanfinder-schema.cjs');

// Shared by the single-product exporter and the future list downloader.
// Offline mode is only for analysing saved references; it marks the output sampleOnly.
function captureProduct({ postId, editUrl, offline = false, capturedAt, sourceFile, siteUrl, schemaVersion }) {
  const nullable = value => value == null || String(value).trim() === '' ? null : String(value).replace(/\r\n?/g, '\n');
  const positive = value => /^[1-9]\d*$/.test(String(value || '')) && Number.isSafeInteger(Number(value)) ? Number(value) : null;
  const one = selector => {
    const nodes = document.querySelectorAll(selector);
    if (nodes.length !== 1) throw new Error(`Expected one product control: ${selector}`);
    return nodes[0];
  };
  const value = selector => {
    // Fresh editor loads expose the saved HTML source in the textarea. Reading
    // TinyMCE would reserialize tags/entities and introduce artificial differences.
    return nullable(one(selector).value);
  };
  if (!offline) {
    const url = new URL(location.href);
    if (url.origin !== siteUrl || url.pathname !== '/wp-admin/post.php' || url.searchParams.get('post') !== String(postId) || one('[name="post_ID"]').value !== String(postId) || one('[name="post_type"]').value !== 'product') throw new Error('Unexpected product identity during capture.');
  }
  const tabs = {}, tabLabels = {};
  for (const box of document.querySelectorAll('.woocommerce_product_tab')) {
    const title = box.querySelector('input[name^="product_tab_title["]');
    const match = /^product_tab_title\[(\d+)\]$/.exec(title?.name || '');
    if (!match) throw new Error('Could not identify a product tab form index.');
    const index = match[1];
    if (tabs[index]) throw new Error(`Duplicate tab index ${index}.`);
    const classes = [...box.classList];
    const custom = classes.map(c => /^product_tab_(\d+)$/.exec(c)).find(Boolean);
    const core = classes.find(c => c.startsWith('core_tab_'));
    if (!custom && !core) throw new Error(`Unknown tab identity ${index}.`);
    const tab = { tabId: custom ? Number(custom[1]) : core.slice(9), kind: custom ? 'custom' : 'core', position: Number(box.getAttribute('rel')), title: nullable(title.value) };
    const heading = box.querySelector(`[name="product_tab_heading[${index}]"]`);
    const content = box.querySelector(`[name="product_tab_content[${index}]"]`);
    if (heading) tab.heading = nullable(heading.value);
    if (content) tab.content = value(`#${content.id}`);
    tabs[index] = tab;
    tabLabels[index] = box.querySelector('.product_tab_name')?.textContent.trim() || tab.title;
  }
  const categories = {}, categoryLabels = {};
  for (const el of document.querySelectorAll('#product_catchecklist input[name="tax_input[product_cat][]"]')) {
    const id = positive(el.value);
    if (!id || Object.hasOwn(categories, id)) throw new Error('Invalid or duplicate category ID.');
    categories[id] = el.checked;
    categoryLabels[id] = el.closest('label')?.textContent.replace(/\s+/g, ' ').trim() || null;
  }
  if (!Object.keys(categories).length) throw new Error('Product category checklist missing.');
  const images = [...document.querySelectorAll('#woocommerce-product-images li.image[data-attachment_id]')].map((el, index) => ({ attachmentId: positive(el.dataset.attachment_id), position: index + 1 }));
  if (images.some(image => !image.attachmentId)) throw new Error('Invalid gallery attachment ID.');
  // Thumbnail addresses only help the Review hub show the images; they are audit data, not edited.
  const galleryPreviews = [...document.querySelectorAll('#woocommerce-product-images li.image[data-attachment_id]')].map(el => ({ attachmentId: positive(el.dataset.attachment_id), url: nullable(el.querySelector('img')?.getAttribute('src')) })).filter(item => item.url && /^https?:/i.test(item.url));
  const thumbnail = document.querySelector('#_thumbnail_id, input[name="_thumbnail_id"]');
  let featuredId = positive(thumbnail?.value);
  let featuredImageIdSource = thumbnail ? 'hidden_input' : 'unavailable';
  if (!thumbnail && !offline) {
    const settings = window.wp?.media?.view?.settings?.post || window._wpMediaViewsL10n?.settings?.post;
    if (settings && (settings.id == null || Number(settings.id) === postId) && Object.prototype.hasOwnProperty.call(settings, 'featuredImageId')) {
      featuredId = positive(settings.featuredImageId);
      featuredImageIdSource = 'wordpress_media_settings';
    }
  }
  const preview = document.querySelector('#postimagediv img');
  const warnings = [];
  if (offline) warnings.push('The saved reference does not expose a featured-image attachment ID. Capture a live product before generating an edit report.');
  else if (featuredImageIdSource === 'unavailable' && preview) warnings.push('This legacy featured-image box does not expose the attachment ID. attachmentId is unknown (null); the image preview is retained in audit.featuredImagePreview.');
  const commerce = {};
  for (const el of document.querySelectorAll('#woocommerce-product-data input[name], #woocommerce-product-data select[name], #woocommerce-product-data textarea[name]')) {
    if (!/^(?:product-type|_(?:virtual|downloadable|sku|product_url|button_text|regular_price|sale_price|sale_price_dates_from|sale_price_dates_to|download_limit|download_expiry|download_type|manage_stock|stock|backorders|stock_status|sold_individually|weight|length|width|height|purchase_note)|product_shipping_class|menu_order|comment_status)$/.test(el.name)) continue;
    commerce[el.name] = el.type === 'checkbox' ? el.checked : nullable(el.value);
  }
  const permalink = document.querySelector('#sample-permalink');
  const data = {
    vehicle: { name: value('#title') },
    descriptionAndImages: { description: value('#content'), short_description: value('#excerpt'), featured_image: { attachmentId: featuredId }, image_gallery: { image_count: images.length, images } },
    productTabs: { override_layout: one('#_override_tab_layout').checked, tabs },
    taxonomies: { product_categories: categories, product_tags: value('#tax-input-product_tag') },
  };
  if (!data.vehicle.name) throw new Error('Cannot capture a blank product title.');
  return {
    schemaVersion, bundleType: 'campervanfinder_vehicle_profile_snapshot',
    capture: { capturedAt: capturedAt || new Date().toISOString(), source: offline ? 'saved_wordpress_product_editor_mhtml_sample' : 'live_wordpress_product_editor', siteUrl, editUrl, postId, postType: 'product', postStatus: document.querySelector('#post_status')?.value || null, locale: document.documentElement.lang || null, slug: nullable(document.querySelector('#post_name')?.value || document.querySelector('#editable-post-name-full')?.textContent), publicUrl: nullable(permalink?.querySelector('a')?.href || permalink?.textContent) },
    data,
    audit: { sampleOnly: offline, ...(sourceFile ? { sourceFile } : {}), categoryLabels, tabLabels, productData: commerce, featuredImageIdSource, galleryPreviews, featuredImagePreview: preview ? { url: preview.src, altText: preview.alt, displayWidth: preview.width, displayHeight: preview.height } : null, warnings },
  };
}

async function captureProfile(page, postId, { country = 'au', ...options } = {}) {
  return page.evaluate(captureProduct, { postId, editUrl: page.url(), ...options, siteUrl: countrySite(country).origin, schemaVersion: SCHEMA_VERSION });
}

function writeCurrent(snapshot, workspace) {
  const { validateSnapshot } = require('./campervanfinder-schema.cjs');
  const country = countryForSite(snapshot.capture?.siteUrl);
  validateSnapshot(snapshot, { country });
  const folder = path.join(workspace, 'current');
  fs.mkdirSync(folder, { recursive: true });
  const name = snapshot.data.vehicle.name.replace(/[<>:"/\\|?*\x00-\x1f]/g, '-').replace(/[. ]+$/g, '').slice(0, 140).replace(/[. ]+$/g, '') || 'vehicle';
  const filename = `${snapshot.capture.postId} - ${country} - ${name}.json`;
  const target = path.join(folder, filename), temp = `${target}.${randomUUID()}.tmp`;
  try { fs.writeFileSync(temp, JSON.stringify(snapshot, null, 2) + '\n', 'utf8'); fs.renameSync(temp, target); }
  finally { if (fs.existsSync(temp)) fs.unlinkSync(temp); }
  for (const old of fs.readdirSync(folder)) {
    if (old !== filename && old.startsWith(`${snapshot.capture.postId} - ${country} - `) && old.endsWith('.json')) fs.unlinkSync(path.join(folder, old));
  }
  return { filename, snapshot };
}

module.exports = { captureProduct, captureProfile, writeCurrent };

const SITE_URL = 'https://www.campervanfinder.com.au';
const COUNTRY_SITES = {
  au: { country: 'au', origin: SITE_URL, folder: 'captures/campervanfinder-au' },
  nz: { country: 'nz', origin: 'https://www.campervanfinder.co.nz', folder: 'captures/campervanfinder-nz' },
};
function countrySite(country = 'au') {
  if (!Object.hasOwn(COUNTRY_SITES, country)) throw new Error('Campervan Finder country must be au or nz.');
  return COUNTRY_SITES[country];
}
function countryForSite(origin) {
  const site = Object.values(COUNTRY_SITES).find(site => site.origin === origin);
  if (!site) throw new Error('Unsupported Campervan Finder website origin.');
  return site.country;
}
const SCHEMA_VERSION = '1.0';
const fieldMappings = [
  { jsonPath: 'data.vehicle.name', selector: '#title', type: 'text' },
  { jsonPath: 'data.descriptionAndImages.description', selector: '#content', type: 'html' },
  { jsonPath: 'data.descriptionAndImages.short_description', selector: '#excerpt', type: 'html' },
  { jsonPath: 'data.productTabs.override_layout', selector: '#_override_tab_layout', type: 'checkbox' },
];

function validateSnapshot(snapshot, { sample = false, country = 'au' } = {}) {
  const siteUrl = countrySite(country).origin;
  if (snapshot?.schemaVersion !== SCHEMA_VERSION || snapshot?.bundleType !== 'campervanfinder_vehicle_profile_snapshot') throw new Error('Expected a Campervan Finder schema 1.0 snapshot.');
  const capture = snapshot.capture;
  if (!Number.isSafeInteger(capture?.postId) || capture.postId <= 0 || capture.postType !== 'product' || capture.siteUrl !== siteUrl) throw new Error('Invalid Campervan Finder product identity.');
  const url = new URL(capture.editUrl);
  if (url.origin !== siteUrl || url.pathname !== '/wp-admin/post.php' || url.searchParams.get('post') !== String(capture.postId) || url.searchParams.get('action') !== 'edit') throw new Error('Invalid Campervan Finder editor URL.');
