    if (!Array.isArray(runIds) || !runIds.length || runIds.length > 50 || new Set(runIds).size !== runIds.length) throw new HttpError(400, 'Choose the reports to save.');
    const waiting = new Set(items.filter(item => ['queued', 'saving'].includes(item.status)).map(item => item.runId));
    const chosen = runIds.map(runId => {
      const state = runState(workspace, runId).state;
      if (waiting.has(runId)) throw new HttpError(409, `${titleOf(runId)} is already waiting to save.`);
      if (!SAVEABLE.includes(state)) throw new HttpError(409, `${titleOf(runId)} is not approved (${state}).`);
      return { runId, createdAt: store.readJson(path.join(runFolder(workspace, runId), 'plan.json')).createdAt };
    }).sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
    items = [...items.filter(item => ['queued', 'saving'].includes(item.status) || Date.now() - Date.parse(item.endedAt || 0) < 6 * 3600e3).slice(-30),
      ...chosen.map(({ runId }) => ({ runId, title: titleOf(runId), status: 'queued', queuedAt: new Date().toISOString(), lines: [] }))];
    work();
    return snapshot();
  }
  function cancel(runId) {
    items = items.filter(item => item.status !== 'queued' || (runId && item.runId !== runId));
    return snapshot();
  }
  const statusOf = runId => [...items].reverse().find(item => item.runId === runId)?.status || null;
  return { enqueue, cancel, snapshot, statusOf, idle: () => new Promise(resolve => { const check = () => active ? setTimeout(check, 20) : resolve(); check(); }) };
}

function staticFile(workspace, urlPath) {
  if (urlPath === '/' || urlPath === '/index.html') return staticFile(workspace, '/hub/index.html');
  const prefix = Object.keys(STATIC).find(key => urlPath.startsWith(key));
  if (!prefix) return null;
  const name = decodeURIComponent(urlPath.slice(prefix.length));
  if (!/^[\w .-]+$/.test(name) || !TYPES[path.extname(name).toLowerCase()]) return null;
  const file = store.inside(workspace, path.join(STATIC[prefix], name));
  return fs.existsSync(file) ? { bytes: fs.readFileSync(file), type: TYPES[path.extname(name).toLowerCase()] } : null;
}

function readBody(request) {
  return new Promise((resolve, reject) => {
    let size = 0; const chunks = [];
    request.on('data', chunk => { size += chunk.length; if (size > MAX_BODY) { reject(new HttpError(413, 'Request too large.')); request.destroy(); } else chunks.push(chunk); });
    request.on('end', () => { try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')); } catch { reject(new HttpError(400, 'Invalid JSON.')); } });
    request.on('error', reject);
  });
}

// Only same-machine pages can use the API: the Host header must name this
// server (blocks DNS rebinding) and writes need the per-start token, which a
// cross-origin page cannot read because no CORS headers are ever sent.
function createServer(workspace = root, { token = randomBytes(24).toString('hex'), runner } = {}) {
  const queue = createQueue(workspace, runner);
  const server = http.createServer(async (request, response) => {
    const send = (status, body, type = 'application/json; charset=utf-8') => {
      response.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer' });
      response.end(Buffer.isBuffer(body) || typeof body === 'string' ? body : JSON.stringify(body));
    };
    try {
      const port = server.address().port;
      if (![`127.0.0.1:${port}`, `localhost:${port}`].includes(request.headers.host)) throw new HttpError(403, 'Unexpected host.');
      const url = new URL(request.url, `http://127.0.0.1:${port}`), parts = url.pathname.split('/').filter(Boolean);
      if (request.method === 'POST') {
        if (request.headers['x-review-token'] !== token) throw new HttpError(403, 'Missing review token. Reload the page.');
        if (!String(request.headers['content-type'] || '').startsWith('application/json')) throw new HttpError(415, 'Send JSON.');
        const body = await readBody(request);
        if (parts[0] === 'api' && parts[1] === 'runs' && parts[3] === 'decision' && parts.length === 4) return send(200, decide(workspace, parts[2], body));
        if (parts[0] === 'api' && parts[1] === 'runs' && parts[3] === 'edits' && parts.length === 4) return send(200, saveEdits(workspace, parts[2], body));
        if (url.pathname === '/api/bundles/save') return send(200, saveReviewedBundle(workspace, body.file, body.reviewed));
        if (url.pathname === '/api/queue/save') return send(200, queue.enqueue(body.runIds));
        if (url.pathname === '/api/queue/cancel') return send(200, queue.cancel(body.runId || null));
        throw new HttpError(404, 'Not found.');
      }
      if (request.method !== 'GET') throw new HttpError(405, 'Method not allowed.');
      if (url.pathname === '/api/session') return send(200, { token });
      if (url.pathname === '/api/items') return send(200, { updates: listRuns(workspace).map(item => ({ ...item, queue: queue.statusOf(item.id) })), newVehicles: listBundles(workspace), queue: queue.snapshot() });
      if (url.pathname === '/api/queue') return send(200, queue.snapshot());
      if (parts[0] === 'api' && parts[1] === 'runs' && parts.length === 3) return send(200, runDetail(workspace, parts[2]));
      if (parts[0] === 'api' && parts[1] === 'runs' && parts[3] === 'uploads' && parts.length === 6) {
        const file = uploadFile(workspace, parts[2], parts[4], parts[5]);
        return send(200, file.bytes, file.type);
      }
      if (url.pathname === '/api/bundles') return send(200, bundleDetail(workspace, url.searchParams.get('file')));
      const file = staticFile(workspace, url.pathname);
      if (file) return send(200, file.bytes, file.type);
      throw new HttpError(404, 'Not found.');
    } catch (error) {
      send(error.status || 500, { error: error.message });
    }
  });
  return { server, token, queue };
}

function parseArgs(args) {
  const options = { port: 8787, open: true, run: null };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--no-open') options.open = false;
    else if (args[i] === '--port' && /^\d+$/.test(args[i + 1] || '') && Number(args[i + 1]) < 65536) options.port = Number(args[++i]);
    else if (args[i] === '--run' && RUN_ID.test(args[i + 1] || '')) options.run = args[++i];
    else throw new Error('Usage: review-hub.cjs [--port 8787] [--no-open] [--run RUN-...]');
  }
  return options;
}
function main(args = process.argv.slice(2)) {
  const options = parseArgs(args), { server } = createServer(root);
  server.on('error', error => {
    if (error.code === 'EADDRINUSE') console.error(`Port ${options.port} is in use. The hub may already be open at http://127.0.0.1:${options.port}/ (or pass --port).`);
    else console.error(error.message);
    process.exitCode = 1;
  });
  server.listen(options.port, '127.0.0.1', () => {
    const url = `http://127.0.0.1:${server.address().port}/${options.run ? `?run=${options.run}` : ''}`;
    console.log(`Review hub: ${url}\nKeep this window open while reviewing. Close it (Ctrl+C) when finished.`);
    if (options.open && process.platform === 'win32') spawn('cmd', ['/c', 'start', '', url], { detached: true, stdio: 'ignore' }).unref();
  });
  return server;
}

if (require.main === module) main();
module.exports = { runState, listRuns, listBundles, runDetail, decide, saveEdits, createQueue, uploadFile, bundleDetail, saveReviewedBundle, staticFile, createServer, parseArgs };

// Multi-source comparison bundles (schema 3.0) for new Motorhome Hire frontend
// profiles: create a skeleton from a draft, validate it, and apply a reviewed
// bundle's choices into the draft. Offline only. See "Source comparison/AGENTS.md".
const fs = require('node:fs');
const path = require('node:path');
const store = require('./catalog-store.cjs');
const SC = require('../Source comparison/source-compare.js');
const schema = require('./motorhomehire-frontend-schema.cjs');
const drafts = require('./motorhomehire-frontend-draft.cjs');
const { root } = require('./project.cjs');

const MARKETS = { au: 'Australia', nz: 'New Zealand', us: 'USA' };
const bundleFile = draftFile => draftFile.replace(/\.json$/, '.sources.json');
// Draft keeps the site's icon text; bundles use Booleans like the reviewer script.
const ICONS = { 'featuresIcons.toilets': ['Toilet', 'notoilet'], 'featuresIcons.showers': ['Shower', 'noshower'] };
const iconText = (bundlePath, value) => value ? ICONS[bundlePath][0] : `<span class="${ICONS[bundlePath][1]}">${ICONS[bundlePath][0]}</span>`;
// Textareas store "<br>" followed by a newline, matching saved editor values.
const textareaPaths = new Set(SC.FIELDS.filter(f => f.type === 'textarea').map(f => f.path));
function toDraftValue(bundlePath, value) {
  if (value === null) return null;
  if (ICONS[bundlePath]) return iconText(bundlePath, value);
  if (typeof value === 'string') {
    const text = SC.normalizeText(value);
    return textareaPaths.has(bundlePath) ? text.replace(/<br>/g, '<br>\n') : text;
  }
  return Array.isArray(value) ? [...new Set(value.map(v => SC.normalizeText(v)))] : value;
}

function initBundle(workspace, draftRelative) {
  const draftPath = store.inside(workspace, draftRelative), draft = store.readJson(draftPath), out = bundleFile(draftPath);
  if (draft.draftType !== schema.DRAFT_TYPE) throw new Error('Expected a frontend draft created by motorhomehire-frontend-draft.cjs --init.');
  if (fs.existsSync(out)) throw new Error(`A sources bundle already exists: ${path.relative(workspace, out)}.`);
  const bundle = { schemaVersion: '3.0', bundleType: 'vehicle_multi_source_comparison',
    targetVehicle: { workingName: draft.data.vehicle.name, market: MARKETS[draft.identity.country] || null, vehicleId: draft.vehicleId, primarySourceId: null, scrapedAt: new Date().toISOString().slice(0, 10) },
    comparisonPolicy: { nullIsNoClaim: true, autoSelectWhenOneUniqueNonNullValue: true, requireManualSelectionWhenNonNullValuesConflict: true, compareArraysAsUnorderedSets: true, normalizeWhitespaceBeforeComparison: true },
    sources: [], aiProposals: {}, review: { status: 'not_started', selections: {} },
    sourceTemplate: { sourceId: 'replace_me', sourceType: 'official', sourceName: 'Replace me', url: 'https://replace.me/exact-vehicle-page', scrapedAt: bundleDate(), status: 'scraped', notes: [], data: SC.blankData(), evidence: {} } };
  store.atomicWrite(out, bundle);
  return out;
}
function bundleDate() { return new Date().toISOString().slice(0, 10); }

function checkBundle(workspace, relative) {
  const bundle = store.readJson(store.inside(workspace, relative)), errors = [];
  if ('sourceTemplate' in bundle) errors.push('Remove sourceTemplate after copying it into sources.');
  errors.push(...SC.validateBundle(bundle));
  const entries = errors.length ? [] : SC.compareBundle(bundle);
  const warnings = bundle.sources?.flatMap(s => SC.sourceWarnings(s).map(w => `${s.sourceId}: ${w}`)) || [];
  for (const e of entries) {
    if (e.proposal && e.proposalProblems.length) errors.push(`aiProposals.${e.field.path}: ${e.proposalProblems.join(' ')}`);
    else if (e.state === 'conflict' && !e.proposal) warnings.push(`${e.field.path}: conflict without an AI proposal.`);
    for (const c of e.candidates) if (SC.isClaim(c.value)) for (const i of SC.formatIssues(e.field.path, c.value)) if (i.level === 'warning') warnings.push(`${c.sourceId} ${e.field.path}: ${i.message}`);
  }
  const count = state => entries.filter(e => e.state === state).length;
  return { bundle, errors, warnings, entries, counts: { conflict: count('conflict'), agreed: count('agreed'), single: count('single'), none: count('none') } };
}

function draftSource(bundle, sourceId) {
  const s = bundle.sources.find(source => source.sourceId === sourceId);
  return s.sourceType === 'official' ? { type: 'official', url: s.url, note: s.sourceName } : { type: s.sourceType, url: s.url, note: s.sourceName };
}
function applyReview(workspace, reviewedRelative, draftRelative) {
  const checked = checkBundle(workspace, reviewedRelative);
  if (checked.errors.length) throw new Error(`The bundle has errors; run --check:\n- ${checked.errors.join('\n- ')}`);
  const { bundle, entries } = checked, draftPath = store.inside(workspace, draftRelative), draft = store.readJson(draftPath);
  if (bundle.targetVehicle?.vehicleId && bundle.targetVehicle.vehicleId !== draft.vehicleId) throw new Error(`The bundle is for ${bundle.targetVehicle.vehicleId}, not ${draft.vehicleId}.`);
  const problems = [], applied = [], kept = [];
  for (const entry of entries) {
    const selection = bundle.review?.selections?.[entry.field.path];
    const problem = SC.checkSelection(entry, selection);
    if (problem) { problems.push(`${entry.field.path}: ${problem}`); continue; }
    const choice = selection ? { mode: selection.selectionMode, value: selection.value, sourceIds: selection.selectionMode === 'ai' ? entry.proposal.sourceIds : entry.groups.find(g => SC.same(g.value, selection.value))?.sourceIds || [] } : SC.defaultChoice(entry);
    const draftPathKey = `data.${entry.field.path}`;
    if (choice.value === null) { kept.push(draftPathKey); continue; }
    store.set(draft, schema.pointer(draftPathKey), toDraftValue(entry.field.path, choice.value));
    const sources = choice.sourceIds.map(id => draftSource(bundle, id));
    if (choice.mode === 'ai' && entry.proposal.basis === 'derived') sources.unshift({ type: 'derived', note: `AI proposal accepted in review: ${entry.proposal.note}` });
    draft.sources[draftPathKey] = sources;
    applied.push(draftPathKey);
  }
  if (problems.length) throw new Error(`Review is incomplete or does not match the bundle:\n- ${problems.join('\n- ')}`);
  store.atomicWrite(draftPath, draft);
  return { applied, kept, check: drafts.checkDraft(workspace, draftRelative) };
}

function main(args = process.argv.slice(2), workspace = root) {
  if (args.length === 1 && args[0] === '--help') { console.log('Multi-source bundles for new Motorhome Hire frontend profiles (offline):\n  --init DRAFT.json              create <draft>.sources.json to fill per "Source comparison/AGENTS.md"\n  --check BUNDLE.json            validate sources, formats and AI proposals\n  --apply REVIEWED.json DRAFT.json  write reviewed choices into the draft, then check it\nReview bundles in "Source comparison/index.html".'); return; }
  if (args[0] === '--init' && args.length === 2) { const out = initBundle(workspace, args[1]); console.log(`Bundle: ${path.relative(workspace, out)}`); return out; }
  if (args[0] === '--check' && args.length === 2) {
    const r = checkBundle(workspace, args[1]);
    for (const e of r.errors) console.log(`ERROR ${e}`);
    for (const w of r.warnings) console.log(`warning ${w}`);
    console.log(`${r.errors.length ? 'invalid' : 'valid'}: ${r.counts.conflict} conflict(s), ${r.counts.agreed} agreed, ${r.counts.single} single-source, ${r.counts.none} without data; ${r.errors.length} error(s), ${r.warnings.length} warning(s).`);
    if (r.errors.length) process.exitCode = 1;
    return r;
  }
  if (args[0] === '--apply' && args.length === 3) {
    const r = applyReview(workspace, args[1], args[2]);
    console.log(`Applied ${r.applied.length} field(s); ${r.kept.length} had no source value and kept the draft value.\nDraft ${r.check.status}: ${path.relative(workspace, r.check.file.replace(/\.json$/, '.report.txt'))}`);
    return r;
  }
  throw new Error('Use --help for bundle commands.');
}
if (require.main === module) { try { main(); } catch (error) { console.error(error.message); process.exitCode = 1; } }
module.exports = { bundleFile, toDraftValue, initBundle, checkBundle, applyReview, main };

"""Find a saved vehicle offline and return its file, full JSON or selected fields."""

import argparse
import json
from pathlib import Path
import re
import sys
import unicodedata

DEFAULT_CATALOG = Path(__file__).resolve().parents[1] / "catalog" / "current"
COUNTRIES = ("au", "nz", "ca", "us")
VEHICLE_ID = re.compile(r"veh_[0-9]{6,}$")


class LookupError(ValueError):
    pass


def normalize(value):
    """Ignore case, punctuation and spacing, including Hi5 versus Hi 5."""
    return "".join(c for c in unicodedata.normalize("NFKC", value).casefold() if c.isalnum())


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise LookupError(f"Duplicate JSON key: {key}")
        result[key] = value
    return result


def invalid_constant(value):
    raise LookupError(f"Invalid JSON constant: {value}")


def text(value):
    return value if isinstance(value, str) else ""


def is_link(path):
    return path.is_symlink() or (hasattr(path, "is_junction") and path.is_junction())


def site_records(record):
    for site_id, site in sorted(record["sites"].items()):
        if not isinstance(site, dict) or not isinstance(site.get("records"), dict):
            raise LookupError(f"Invalid site records: {site_id}")
        for external_id, external in sorted(site["records"].items()):
            if not isinstance(external, dict):
                raise LookupError(f"Invalid site record: {site_id}:{external_id}")
            observed, mapping = external.get("observed"), external.get("mapping")
            if not isinstance(observed, dict) or not isinstance(mapping, dict):
                raise LookupError(f"Missing observation/mapping: {site_id}:{external_id}")
            snapshot = observed.get("snapshot")
            if not isinstance(snapshot, dict):
                raise LookupError(f"Missing snapshot: {site_id}:{external_id}")
            data, fields = snapshot.get("data", {}), snapshot.get("fields", {})
            vehicle = data.get("vehicle", {}) if isinstance(data, dict) else {}
            name = text(vehicle.get("name")) if isinstance(vehicle, dict) else ""
            if not name and isinstance(fields, dict):
                name = text(fields.get("name")) or text(fields.get("vehicle_name"))
            yield {
                "siteId": site_id,
                "externalId": external_id,
                "name": name or None,
                "mappingStatus": mapping.get("status"),
                "capturedAt": observed.get("capturedAt"),
                "captureStatus": observed.get("captureStatus"),
            }


def load_catalog(directory):
    directory = Path(directory).absolute()
    if is_link(directory):
        raise LookupError("A catalog directory must not be a symbolic link/junction")
    if not directory.exists():
        return []
    if not directory.is_dir():
        raise LookupError("The catalog path must be a directory")
    entries, seen = [], set()
    for country in COUNTRIES:
        folder = directory / country
        if is_link(folder):
            raise LookupError(f"Symbolic link/junction in catalog: {folder}")
        if not folder.exists():
            continue
        if not folder.is_dir():
            raise LookupError(f"Country catalog must be a directory: {folder}")
        for file in sorted(folder.glob("*.json")):
            if is_link(file):
                raise LookupError(f"Symbolic link/junction in catalog: {file}")
            try:
                record = json.loads(file.read_text(encoding="utf-8-sig"), object_pairs_hook=unique_object, parse_constant=invalid_constant)
                if not isinstance(record, dict) or record.get("schemaVersion") != "1.0" or record.get("recordType") != "vehicleCatalogRecord":
                    raise LookupError("Expected a vehicle catalog record schema 1.0")
                vehicle_id = record.get("vehicleId")
                if not isinstance(vehicle_id, str) or not VEHICLE_ID.fullmatch(vehicle_id):
                    raise LookupError("Invalid permanent vehicle ID")
                if vehicle_id in seen:
                    raise LookupError(f"Duplicate permanent vehicle ID: {vehicle_id}")
                identity = record.get("identity")
                if not isinstance(identity, dict) or identity.get("country") != country:
                    raise LookupError("Country directory disagrees with vehicle identity")
                for key in ("brand", "model"):
                    if not normalize(text(identity.get(key))):
                        raise LookupError(f"Missing vehicle {key}")
                if not file.name.startswith(f"{vehicle_id} - {country} - "):
                    raise LookupError("Filename disagrees with vehicle ID/country")
                revision = record.get("catalogRevision")
                if type(revision) is not int or revision < 1 or not isinstance(record.get("sites"), dict):
                    raise LookupError("Missing catalog revision/sites")
                sites = list(site_records(record))
                seen.add(vehicle_id)
                names = [identity["model"], f'{identity["brand"]} {identity["model"]}']
                variant = text(identity.get("variant"))
                if variant:
                    names.extend([f'{identity["model"]} {variant}', f'{identity["brand"]} {identity["model"]} {variant}'])
                names.extend(site["name"] for site in sites if site["name"])
                entries.append({"file": file, "record": record, "names": {normalize(name) for name in names}, "sites": sites})
            except (OSError, ValueError) as error:
                raise LookupError(f"{file}: {error}") from error
    return entries


def summary(entry):
    record = entry["record"]
    return {
        "vehicleId": record["vehicleId"],
        "file": entry["file"].as_posix(),
        "identity": record["identity"],
        "catalogRevision": record["catalogRevision"],
        "sites": entry["sites"],
    }


def field_value(record, pointer):
    if not pointer.startswith("/") or re.search(r"~(?![01])", pointer):
        raise LookupError(f"Use a JSON Pointer beginning with /: {pointer}")
    value = record
    for token in pointer[1:].split("/"):
        key = token.replace("~1", "/").replace("~0", "~")
        if isinstance(value, dict) and key in value:
            value = value[key]
        elif isinstance(value, list) and re.fullmatch(r"0|[1-9]\d*", key) and int(key) < len(value):
            value = value[int(key)]
        else:
            raise LookupError(f"Saved field does not exist: {pointer}")
    return value


def lookup(directory, *, name=None, vehicle_id=None, country=None, brand=None, exact=False, full=False, fields=()):
    if bool(name) == bool(vehicle_id):
        raise LookupError("Supply either a vehicle name or a permanent vehicle ID")
    if country is not None and country not in COUNTRIES:
        raise LookupError("Country must be au, nz, ca or us")
    if name is not None and not normalize(name):
        raise LookupError("Vehicle name must contain letters or numbers")
    if vehicle_id is not None and not VEHICLE_ID.fullmatch(vehicle_id):
        raise LookupError("Use a permanent vehicle ID such as veh_000021")
    if brand is not None and not normalize(brand):
        raise LookupError("Brand must contain letters or numbers")
    if full and fields:
        raise LookupError("Choose either --full or --field")
    query = {key: value for key, value in {"name": name, "vehicleId": vehicle_id, "country": country, "brand": brand}.items() if value is not None}
    matches = []
    needle = normalize(name) if name is not None else None
    for entry in load_catalog(directory):
        record, identity = entry["record"], entry["record"]["identity"]
        if country is not None and identity["country"] != country:
            continue
        if brand is not None and normalize(brand) not in {normalize(identity["brand"]), normalize(text(identity.get("supplierKey")))}:
            continue
        if vehicle_id is not None:
            matched = record["vehicleId"] == vehicle_id
        else:
            matched = needle in entry["names"] if exact else any(needle in candidate for candidate in entry["names"])
        if matched:
            matches.append(entry)
    result = {"offline": True, "query": query}
    if not matches:
        return {**result, "status": "missing", "nextAction": "checkNameCountryOrCapture", "matches": []}
    if len(matches) != 1:
        return {**result, "status": "ambiguous", "nextAction": "refineNameCountryBrandOrId", "matches": [summary(entry) for entry in matches]}
    entry = matches[0]
    result.update(status="found", nextAction="useStoredVehicle", **summary(entry))
    if full:
        result["data"] = entry["record"]
    elif fields:
        result["fields"] = {pointer: field_value(entry["record"], pointer) for pointer in fields}
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--catalog", type=Path, default=DEFAULT_CATALOG, help="Current catalog directory (default: project catalog/current)")
    query = parser.add_mutually_exclusive_group(required=True)
    query.add_argument("--name", help="Canonical model or a saved website vehicle name; partial names are supported")
    query.add_argument("--id", dest="vehicle_id", help="Exact permanent veh_ ID")
    parser.add_argument("--country", choices=COUNTRIES)
    parser.add_argument("--brand", help="Exact catalog brand or supplier key")
    parser.add_argument("--exact", action="store_true", help="Match complete names only, still ignoring case, punctuation and spacing")
    output = parser.add_mutually_exclusive_group()
    output.add_argument("--full", action="store_true", help="Return the complete saved record only for one unique match")
    output.add_argument("--field", action="append", default=[], help="Return a saved JSON Pointer; repeat for multiple fields")
    args = parser.parse_args(argv)
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    try:
        result = lookup(args.catalog, name=args.name, vehicle_id=args.vehicle_id, country=args.country, brand=args.brand, exact=args.exact, full=args.full, fields=args.field)
    except (LookupError, OSError) as error:
        print(json.dumps({"offline": True, "status": "error", "reason": str(error)}, ensure_ascii=False, indent=2))
        return 1
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


